const DEFAULT_RETRY_COUNT = 250;

function createDirectoryFileLockRuntime(options = {}) {
  const retryCount = options.retryCount ?? DEFAULT_RETRY_COUNT;
  return `${retryCount}|${"retryCount" in options}`;
}

export const results = [
  createDirectoryFileLockRuntime(),
  createDirectoryFileLockRuntime(undefined),
  createDirectoryFileLockRuntime({ retryCount: undefined }),
  createDirectoryFileLockRuntime({ retryCount: 0 }),
];
